CREATE DATABASE SmartConstructionHub;
GO
USE SmartConstructionHub;
GO

CREATE TABLE Clients (Id INT IDENTITY PRIMARY KEY, FullName NVARCHAR(160) NOT NULL, PhoneNumber NVARCHAR(40), Email NVARCHAR(180), Address NVARCHAR(300), PropertyLocation NVARCHAR(300), Notes NVARCHAR(MAX));
CREATE TABLE Projects (Id INT IDENTITY PRIMARY KEY, ProjectNumber NVARCHAR(40) NOT NULL UNIQUE, ClientId INT NOT NULL, Name NVARCHAR(200) NOT NULL, TypeOfWork NVARCHAR(100), Location NVARCHAR(300), StartDate DATE, ExpectedCompletionDate DATE, Status NVARCHAR(40) NOT NULL, ContractAmount DECIMAL(18,2) NOT NULL, CONSTRAINT FK_Projects_Clients FOREIGN KEY (ClientId) REFERENCES Clients(Id));
CREATE TABLE HousePlans (Id INT IDENTITY PRIMARY KEY, ProjectId INT NOT NULL, Name NVARCHAR(200) NOT NULL, FilePath NVARCHAR(500), Bedrooms INT, Bathrooms INT, RoofDesign NVARCHAR(100), BuildingArea DECIMAL(18,2), Dimensions NVARCHAR(200), FOREIGN KEY (ProjectId) REFERENCES Projects(Id) ON DELETE CASCADE);
CREATE TABLE Estimates (Id INT IDENTITY PRIMARY KEY, EstimateNumber NVARCHAR(40) NOT NULL UNIQUE, ProjectId INT NOT NULL, CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), Status NVARCHAR(40) NOT NULL, FOREIGN KEY (ProjectId) REFERENCES Projects(Id) ON DELETE CASCADE);
CREATE TABLE EstimateItems (Id INT IDENTITY PRIMARY KEY, EstimateId INT NOT NULL, Material NVARCHAR(160) NOT NULL, Quantity DECIMAL(18,3) NOT NULL, Unit NVARCHAR(30) NOT NULL, UnitPrice DECIMAL(18,2) NOT NULL, FOREIGN KEY (EstimateId) REFERENCES Estimates(Id) ON DELETE CASCADE);
CREATE TABLE Payments (Id INT IDENTITY PRIMARY KEY, ProjectId INT NOT NULL, PaymentDate DATETIME2 NOT NULL, Amount DECIMAL(18,2) NOT NULL, PaymentMethod NVARCHAR(40), ReceiptNumber NVARCHAR(80), Notes NVARCHAR(500), FOREIGN KEY (ProjectId) REFERENCES Projects(Id) ON DELETE CASCADE);
CREATE TABLE Materials (Id INT IDENTITY PRIMARY KEY, Name NVARCHAR(160) NOT NULL, Unit NVARCHAR(30) NOT NULL, QuantityPurchased DECIMAL(18,3) NOT NULL, QuantityUsed DECIMAL(18,3) NOT NULL, Supplier NVARCHAR(160), PurchasePrice DECIMAL(18,2) NOT NULL);
CREATE TABLE Workers (Id INT IDENTITY PRIMARY KEY, WorkerNumber NVARCHAR(40) NOT NULL UNIQUE, FullName NVARCHAR(160) NOT NULL, Phone NVARCHAR(40), Skill NVARCHAR(100), Rate DECIMAL(18,2) NOT NULL, RatePeriod NVARCHAR(20) NOT NULL);
CREATE TABLE ProjectWorkers (ProjectId INT NOT NULL, WorkerId INT NOT NULL, AmountPaid DECIMAL(18,2) NOT NULL, AttendanceNotes NVARCHAR(500), PRIMARY KEY (ProjectId, WorkerId), FOREIGN KEY (ProjectId) REFERENCES Projects(Id) ON DELETE CASCADE, FOREIGN KEY (WorkerId) REFERENCES Workers(Id) ON DELETE CASCADE);
CREATE TABLE ProjectDocuments (Id INT IDENTITY PRIMARY KEY, ProjectId INT NOT NULL, Name NVARCHAR(200) NOT NULL, DocumentType NVARCHAR(80) NOT NULL, FilePath NVARCHAR(500) NOT NULL, UploadedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), FOREIGN KEY (ProjectId) REFERENCES Projects(Id) ON DELETE CASCADE);
CREATE TABLE ProjectPhotos (Id INT IDENTITY PRIMARY KEY, ProjectId INT NOT NULL, Category NVARCHAR(60) NOT NULL, FilePath NVARCHAR(500) NOT NULL, Caption NVARCHAR(300), UploadedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), FOREIGN KEY (ProjectId) REFERENCES Projects(Id) ON DELETE CASCADE);
